examples.template:
LazyVGrid(
    columns: Array(
        repeating: GridItem(.flexible(), spacing: theme.spacing.space3),
        count: dynamicTypeSize.isAccessibilitySize ? 1 : 2
    ),
    spacing: theme.spacing.space3
) {
    MonarchStatCard(
        {{items.0.label}},
        value: {{items.0.value}},
        change: MonarchMetricChange({{items.0.change}}, comparison: {{items.0.caption}}, goodDirection: {{items.0.goodDirection|case}}),
        format: {{items.0.format|case}}
    )
    MonarchStatCard(
        {{items.1.label}},
        value: {{items.1.value}},
        change: MonarchMetricChange({{items.1.change}}),
        format: {{items.1.format|case}}
    )
    MonarchStatCard(
        {{items.2.label}},
        value: {{items.2.value}},
        unit: {{items.2.unit}},
        change: MonarchMetricChange({{items.2.change}}, goodDirection: {{items.2.goodDirection|case}})
    )
    MonarchStatCard({{items.3.label}}, value: {{items.3.value}}, hint: {{items.3.hint}})
}
.accessibilityElement(children: .contain)
.accessibilityLabel({{label}})

examples.code:
ScrollView(.horizontal) {
    LazyHStack(spacing: theme.spacing.space3) {
        ForEach(["Revenue", "Orders", "Refunds"], id: \.self) { label in
            MonarchStatCard(label, value: 1_280, change: MonarchMetricChange(0.05))
                .containerRelativeFrame(.horizontal, count: 5, span: 4, spacing: theme.spacing.space3)
        }
    }
    .scrollTargetLayout()
}
.scrollTargetBehavior(.viewAligned)
.scrollIndicators(.hidden)
.accessibilityElement(children: .contain)
.accessibilityLabel("Today")

VStack(spacing: theme.spacing.space4) {
    LazyVGrid(
        columns: Array(repeating: GridItem(.flexible(), spacing: theme.spacing.space3), count: 2),
        spacing: theme.spacing.space3
    ) {
        ForEach(0..<4, id: \.self) { _ in
            MonarchStatCard("Loading", value: nil, isLoading: true)
        }
    }
    MonarchInlineErrorRetry("The figures didn't load.", variant: .banner, isRetrying: isRetrying) {
        isRetrying = true
    }
}
